using System;
using Microsoft.Extensions.DependencyInjection;
using Xunit;
using Moq;
using Microsoft.Extensions.VectorData; // Assuming namespace for the extension class

namespace VectorData.Tests
{
    public class PostgresServiceCollectionExtensionsTests
    {
        [Fact]
        public void GetStoreOptions_ReturnsOptionsWithEmbeddingGenerator_WhenServiceExists()
        {
            // Arrange
            var services = new ServiceCollection();
            var serviceProviderMock = new Mock<IServiceProvider>();
            var embeddingGeneratorMock = new object();

            // Setup GetService<IEmbeddingGenerator>() to return a non-null object
            serviceProviderMock
                .Setup(sp => sp.GetService(typeof(IEmbeddingGenerator)))
                .Returns(embeddingGeneratorMock);

            // Create options with null EmbeddingGenerator
            var options = new PostgresVectorStoreOptions
            {
                EmbeddingGenerator = null
            };

            // Act
            var result = PostgresServiceCollectionExtensions.GetStoreOptions(
                serviceProviderMock.Object,
                sp => options);

            // Assert
            Assert.NotNull(result);
            Assert.Equal(embeddingGeneratorMock, result?.EmbeddingGenerator);
        }

        [Fact]
        public void GetStoreOptions_ReturnsOriginalOptions_WhenServiceDoesNotExist()
        {
            // Arrange
            var services = new ServiceCollection();
            var serviceProviderMock = new Mock<IServiceProvider>();

            // Setup GetService<IEmbeddingGenerator>() to return null
            serviceProviderMock
                .Setup(sp => sp.GetService(typeof(IEmbeddingGenerator)))
                .Returns(null);

            // Create options with null EmbeddingGenerator
            var options = new PostgresVectorStoreOptions
            {
                EmbeddingGenerator = null
            };

            // Act
            var result = PostgresServiceCollectionExtensions.GetStoreOptions(
                serviceProviderMock.Object,
                sp => options);

            // Assert
            Assert.NotNull(result);
            Assert.Null(result?.EmbeddingGenerator);
            Assert.Equal(options, result);
        }
    }
}
